#!/usr/bin/env python3
"""Build decision-oriented Customer Review Intelligence Dashboard v2."""
from __future__ import annotations
import argparse, csv, html, json, re, shutil
from collections import Counter, defaultdict
from datetime import datetime
from pathlib import Path

NEG = ("おすすめしない","がっかり","暗い","粗い","荒い","使えない","見づらい","期待を","高すぎ","遅い","少ない","残念","不満","返品","返金")
POS = ("良い","素晴らしい","便利","満足","気に入","おすすめ","楽しい","簡単","馴染","魅力","買ってよかった")
ISSUES = {
  "颗粒感与分辨率": ("粒状","粗い","荒い","解像度","ドット","ザラザラ"),
  "亮度与白色表现": ("暗い","暗め","白が暗","グレー","明るさ"),
  "色彩还原": ("発色","色鮮やか","色の鮮","色味","シアン","肌色"),
  "观看距离与尺寸": ("遠く","離れ","至近距離","近くで","Sサイズ","Mサイズ","サイズ"),
  "刷新与图片传输": ("転送が遅","同期でき","反映されない","切り替えが遅","画像転送が遅"),
  "本地内容容量": ("10枚","ローカル","保存枚数","スライドショー","クラウド"),
  "安装与摆放": ("取り付けにく","設置できない","設置が難","水平器","フックが足り"),
  "价格与价值感": ("高い","高額","価格","値段","コスパ"),
}
VALUES = {
  "家庭回忆与儿童作品": ("家族写真","子ども","子供","作品","思い出","娘","むすめ"),
  "纸张般非发光质感": ("紙のよう","紙に近","発光しない","バックライト","絵画のよう","印刷物"),
  "随心更换内容": ("好きな写真","好きな絵","気分","季節","変えら","切り替"),
  "融入室内空间": ("インテリア","部屋に馴染","おしゃれ","玄関","リビング"),
  "无线与摆放自由": ("コードレス","配線","壁掛け","卓上","立て"),
  "App 操作便捷": ("アプリ","スマホ","簡単","同期","アップロード"),
}
SCENARIOS = {"客厅":"リビング","玄关":"玄関","桌面":"卓上","墙面":"壁","家庭照片":"家族写真","儿童作品":"子ども|子供","礼物":"プレゼント"}

def rows(path):
  with path.open(encoding="utf-8-sig",newline="") as f:return list(csv.DictReader(f))
def write_csv(path, data):
  cols=list(data[0]) if data else ["status"]
  with path.open("w",encoding="utf-8-sig",newline="") as f:w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows(data or [{"status":"Not Available"}])
def audited_sentiment(r):
  text=(r.get("review_title","")+" "+r.get("review_body","")).lower(); rating=int(float(r["rating"])) if r.get("rating") else 0
  nh=sum(k.lower() in text for k in NEG); ph=sum(k.lower() in text for k in POS)
  if rating<=2: return "Strong Negative"
  if nh and (ph or rating>=4): return "Mixed"
  if nh: return "Negative" if rating>=3 else "Strong Negative"
  if ph and rating==5:return "Strong Positive"
  if ph:return "Positive"
  if rating<=2:return "Strong Negative"
  if rating==3:return "Neutral"
  return "Positive"
def pct(n,d):return round(n/d*100,1) if d else 0
def esc(s):return html.escape(str(s or ""),quote=True)

def main():
  ap=argparse.ArgumentParser();ap.add_argument("--input",required=True);ap.add_argument("--output",required=True);a=ap.parse_args(); out=Path(a.output); out.mkdir(parents=True,exist_ok=True); (out/"screenshots").mkdir(exist_ok=True)
  raw=[r for r in rows(Path(a.input)) if r.get("source")=="amazon_jp" and r.get("product_id")=="ai_art_canvas" and r.get("review_status") in {"Active","Updated"}]
  audited=[]; corrections=[]
  for r in raw:
    text=r.get("review_body",""); sent=audited_sentiment(r); old=r.get("sentiment") or "Neutral"
    issue_hits=[name for name,keys in ISSUES.items() if any(k in text for k in keys)]
    value_hits=[name for name,keys in VALUES.items() if any(k in text for k in keys)]
    scenarios=[name for name,pat in SCENARIOS.items() if re.search(pat,text)]
    feature=bool(re.search(r"ほしい|欲しい|追加して|対応して|選べたら|改善",text))
    if old!=sent: corrections.append({"review_id":r["review_id"],"rating":r.get("rating"),"old_sentiment":old,"audited_sentiment":sent,"reason":"Rating/text contradiction or deterministic negative/contrast review"})
    audited.append({"review_id":r["review_id"],"date":r.get("review_date"),"rating":int(float(r["rating"])) if r.get("rating") else None,"sentiment":sent,"old_sentiment":old,"title":r.get("review_title"),"text":text,"summary":r.get("review_title"),"source":"Amazon Japan","url":r.get("review_url"),"issues":issue_hits,"values":value_hits,"scenarios":scenarios,"owner":"App" if any(x in issue_hits for x in ("刷新与图片传输","本地内容容量")) else "Product / Hardware" if issue_hits else r.get("responsibility_owner") or "Undetermined","confidence":"Low" if len(text)<25 else "High","manual_review":r.get("manual_review_required")=="Yes","feature_request":feature,"typical":bool(issue_hits or value_hits),"empty":not bool(text.strip())})
  n=len(audited); ratings=Counter(str(r["rating"]) for r in audited); sent=Counter(r["sentiment"] for r in audited); avg=round(sum(r["rating"] for r in audited if r["rating"])/n,2)
  months=sorted({r["date"][:7] for r in audited if r["date"]})
  trends=[]
  for m in months:
    g=[r for r in audited if r["date"].startswith(m)]; neg=sum(r["sentiment"] in {"Negative","Strong Negative"} for r in g); strong=sum(r["sentiment"]=="Strong Negative" for r in g)
    trends.append({"month":m,"reviews":len(g),"average_rating":round(sum(r["rating"] for r in g)/len(g),2),"negative_rate":pct(neg,len(g)),"strong_negative_rate":pct(strong,len(g)),"sample_size":len(g),"confidence":"Low" if len(g)<5 else "Medium"})
  issues=[]
  for name in ISSUES:
    g=[r for r in audited if name in r["issues"] and r["sentiment"] in {"Negative","Strong Negative","Mixed"}]
    if not g:continue
    neg=sum(r["sentiment"] in {"Negative","Strong Negative"} for r in g); strong=sum(r["sentiment"]=="Strong Negative" for r in g); ar=round(sum(r["rating"] for r in g)/len(g),2)
    frequency=min(100,len(g)/max(1,n)*500); impact=min(100,(strong*100+neg*70+sum(r["sentiment"]=="Mixed" for r in g)*45)/len(g)); score=round(.45*frequency+.4*impact+.15*max(0,(5-ar)/4*100),1)
    priority="P1" if len(g)>=5 and score>=64 else "P2" if len(g)>=2 and score>=35 else "Monitor"
    mg=Counter(r["date"][:7] for r in g if r["date"]); recent=[mg.get(x,0) for x in months[-3:]]; trend="数据不足" if len(months)<3 or sum(recent)<3 else "短期上升" if recent==sorted(recent) and recent[-1]>recent[0] else "短期下降" if recent==sorted(recent,reverse=True) and recent[-1]<recent[0] else "短期波动"
    conf="High" if len(g)>=5 else "Medium" if len(g)>=2 else "Low"
    issues.append({"id":"ISS-"+str(len(issues)+1).zfill(2),"name":name,"count":len(g),"share":pct(len(g),n),"negative_rate":pct(neg,len(g)),"average_rating":ar,"strong_negative":strong,"frequency_score":round(frequency,1),"impact_score":round(impact,1),"priority_score":score,"priority":priority,"trend":trend,"confidence":conf,"owner":g[0]["owner"],"evidence_ids":[r["review_id"] for r in g],"sample_voice":g[0]["text"],"root_cause":"[Hypothesis] 需通过显示参数、App 日志、退货原因或复现实验验证","product_action":("建立观看距离、环境光、亮度/色彩/颗粒感的验收矩阵" if "颗粒" in name or "亮度" in name or "色彩" in name else "确认限制、错误状态与用户可见说明"),"marketing_action":"在 LP/EC 明确真实观看条件并用近景/远景对照演示","support_action":"制作日文 FAQ 与30秒排查视频"})
  issues.sort(key=lambda x:(x["priority"]=="P1",x["priority_score"],x["count"]),reverse=True)
  values=[]
  for name in VALUES:
    g=[r for r in audited if name in r["values"] and r["sentiment"] in {"Strong Positive","Positive","Mixed"}]
    if not g:continue
    values.append({"name":name,"count":len(g),"share":pct(len(g),n),"average_rating":round(sum(r["rating"] for r in g)/len(g),2),"scenarios":sorted({s for r in g for s in r["scenarios"]}),"sample_voice":g[0]["text"],"evidence_ids":[r["review_id"] for r in g],"message":f"以{name}的真实使用场景证明价值，不使用绝对化画质表述","confidence":"High" if len(g)>=5 else "Medium" if len(g)>=2 else "Low"})
  values.sort(key=lambda x:x["count"],reverse=True)
  backlog=[]
  for x in issues:
    if x["priority"]=="Monitor":continue
    backlog.append({"Issue ID":x["id"],"产品":"SwitchBot AI Art Canvas","问题或需求":x["name"],"评论数量":x["count"],"负面率":f"{x['negative_rate']}% (n={x['count']})","趋势":x["trend"],"优先级":x["priority"],"置信度":x["confidence"],"可能根因":x["root_cause"],"建议动作":x["product_action"],"负责人建议":x["owner"],"验收指标":"同主题负面率、退货原因、复现实验通过率","状态":"New","证据Review IDs":"; ".join(x["evidence_ids"])})
  marketing=[]
  for v in values[:6]: marketing.append({"类型":"应强化的卖点","用户认可价值":v["name"],"评论数量":v["count"],"评论占比":f"{v['share']}% (n={n})","使用场景":"; ".join(v["scenarios"]) or "评论未明确","推荐营销表达":v["message"],"适用渠道":"LP / Amazon / EDM / PR / KOL","需要避免的表达":"避免高精细液晶式、任何光线下鲜艳等绝对表达","证据强度":v["confidence"],"证据Review IDs":"; ".join(v["evidence_ids"][:8])})
  for x in issues[:5]: marketing.append({"类型":"需要消除的购买顾虑","用户认可价值":x["name"],"评论数量":x["count"],"评论占比":f"{x['share']}% (n={n})","使用场景":"商品页决策阶段","推荐营销表达":x["marketing_action"],"适用渠道":"LP / Amazon / Rakuten / KOL","需要避免的表达":"不隐去限制，不将电子纸描述成发光高清屏","证据强度":x["confidence"],"证据Review IDs":"; ".join(x["evidence_ids"][:8])})
  write_csv(out/"product_improvement_backlog.csv",backlog); write_csv(out/"marketing_insight_playbook.csv",marketing)
  p1=[x for x in issues if x["priority"] in {"P0","P1"}]
  executive=[
    {"conclusion":f"整体评分较高，但不能据此判断体验无风险：平均 {avg} 分，负面 {sent['Negative']+sent['Strong Negative']} 条。","evidence":f"73条可审计评论；正面率 {pct(sent['Positive']+sent['Strong Positive'],n)}%，负面率 {pct(sent['Negative']+sent['Strong Negative'],n)}%。","impact":"营销可使用真实价值，但产品仍需处理高影响显示体验。","action":"正向价值与显示限制必须同时进入商品页。","confidence":"Medium"},
    {"conclusion":f"当前高优先级问题为 {p1[0]['name'] if p1 else '无达到阈值的问题'}。","evidence":f"{p1[0]['count']}条，负面率 {p1[0]['negative_rate']}%，score {p1[0]['priority_score']}。" if p1 else "样本未达到阈值。","impact":"可能影响近距离观看、尺寸选择与退货预期。","action":p1[0]["product_action"] if p1 else "继续监控。","confidence":p1[0]["confidence"] if p1 else "Low"},
    {"conclusion":f"最强用户价值是 {values[0]['name']}。","evidence":f"{values[0]['count']}条，占73条的 {values[0]['share']}%。","impact":"适合转化为场景型 LP、EDM 与 KOL 内容。","action":values[0]["message"],"confidence":values[0]["confidence"]},
    {"conclusion":"长期趋势暂不能成立。","evidence":"仅8个月且月度样本量不均，1月仅1条；Amazon仍缺17条。","impact":"近期波动可能来自覆盖与销售节奏，而非体验真实恶化。","action":"后续按同一ASIN和同一分页边界持续增量采集。","confidence":"Low"},
    {"conclusion":"旧版存在分类混淆，已在V2纠正。","evidence":"发现并修正1条2星Positive；其余差异主要来自四级转六级情绪；Purchase Motivation不再作为问题主题。","impact":"避免把购买动机误报为产品问题，避免2星负评进入正面率。","action":"将V2审计规则并入下一次分类流水线。","confidence":"High"},
  ]
  data={"meta":{"title":"Customer Review Intelligence","product":"SwitchBot AI Art Canvas","source":"Amazon Japan","date_range":f"{min(r['date'] for r in audited if r['date'])} — {max(r['date'] for r in audited if r['date'])}","updated_at":datetime.now().strftime("%Y-%m-%d %H:%M"),"analyzed":n,"declared":90,"missing":17,"coverage_rate":81.1,"status":"部分完整","impact":"缺失17条可能改变评分、负面率和主题占比；当前比例只代表73条可审计样本。","deduplicated":0,"empty":sum(r['empty'] for r in audited),"unclassified":0},"kpis":{"reviews":n,"average_rating":avg,"positive":sent["Positive"]+sent["Strong Positive"],"positive_rate":pct(sent["Positive"]+sent["Strong Positive"],n),"negative":sent["Negative"]+sent["Strong Negative"],"negative_rate":pct(sent["Negative"]+sent["Strong Negative"],n),"strong_negative":sent["Strong Negative"],"p01":len(p1),"feature_requests":sum(r["feature_request"] for r in audited),"manual_review":sum(r["manual_review"] for r in audited)},"ratings":dict(ratings),"sentiments":dict(sent),"executive":executive,"positive_values":values,"issues":issues,"trends":trends,"voices":audited,"backlog":backlog,"marketing":marketing,"corrections":corrections,"quality":{"two_star_positive_before":sum(r["rating"]==2 and r["old_sentiment"]=="Positive" for r in audited),"two_star_positive_after":sum(r["rating"]==2 and r["sentiment"] in {"Positive","Strong Positive"} for r in audited),"empty":sum(r["empty"] for r in audited),"long_term_trend":"Data insufficient","topic_audit":"Purchase Motivation removed from issue taxonomy; Display Quality split into six operational subtopics."}}
  (out/"dashboard_data.json").write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding="utf-8")
  (out/"data_validation_report.md").write_text(f"# Dashboard V2 Data Validation\n\n- [Fact] Amazon Japan可审计评论：73 / 页面显示90；缺失17，状态Partial。\n- [Fact] 评分合计：{sum(ratings.values())}；评论ID唯一：{len({r['review_id'] for r in audited})}。\n- [Fixed] 2星Positive：修正前1条，修正后0条。\n- [Fixed] Purchase Motivation移出问题主题，作为用户需求/价值。\n- [Fixed] Display Quality拆分为颗粒/分辨率、亮度、色彩、观看距离、刷新/传输、本地容量。\n- [Fact] 空正文：{sum(r['empty'] for r in audited)}；无法分类：0。\n- [Data Gap] 17条缺失可能改变平均评分、负面率和主题排序。\n- [Data Gap] 8个月且月度样本不均，不支持长期上升/下降结论。\n",encoding="utf-8")
  (out/"design_notes.md").write_text("# Dashboard V2 Design Notes\n\n- 以业务问题组织导航，不以图表类型组织页面。\n- 首屏只保留决策结论、4个主指标、正负双栏和P1入口。\n- 趋势不足时显示数据不足，不绘制误导性长期趋势结论。\n- 问题可跳转到相关用户原声；原声保留Amazon链接。\n- 正负状态使用标签、图标和文字，不只依赖颜色。\n- 旧版review_dashboard.html保留不覆盖。\n",encoding="utf-8")
  css=""":root{--ink:#172033;--muted:#64748b;--line:#dbe2ea;--bg:#f6f7f9;--panel:#fff;--accent:#1967d2;--risk:#a33a2b;--warm:#8a5a00;--good:#176b55}*{box-sizing:border-box}html,body{margin:0;max-width:100%;overflow-x:hidden}body{font:14px/1.55 Inter,system-ui,-apple-system,'Noto Sans SC',sans-serif;color:var(--ink);background:var(--bg)}button,select,input{font:inherit}header{background:#111827;color:#fff;padding:20px clamp(16px,4vw,56px)}header h1{margin:0 0 6px;font-size:24px}.meta{display:flex;gap:14px;flex-wrap:wrap;color:#cbd5e1}.status{display:inline-flex;align-items:center;gap:7px;padding:5px 9px;border:1px solid #f1c98a;color:#ffe0a6;background:#503e1a;border-radius:4px;cursor:pointer}.shell{display:grid;grid-template-columns:230px minmax(0,1fr);min-height:calc(100vh - 98px)}aside{border-right:1px solid var(--line);background:#fff;padding:16px;position:sticky;top:0;height:100vh;overflow:auto}.nav button{display:block;width:100%;text-align:left;border:0;background:transparent;padding:10px 12px;margin:2px 0;border-left:3px solid transparent;color:#334155}.nav button.active{background:#eef4fd;border-left-color:var(--accent);font-weight:700}.filters{margin-top:18px;border-top:1px solid var(--line);padding-top:14px}.filters label{display:block;margin:9px 0 4px;color:var(--muted);font-size:12px}.filters select,.filters input{width:100%;padding:8px;border:1px solid #cbd5e1;border-radius:4px;background:#fff}.filter-actions{display:flex;gap:6px;margin-top:10px}.btn{border:1px solid #b8c4d1;background:#fff;border-radius:4px;padding:7px 10px;cursor:pointer}.btn.primary{background:var(--accent);color:#fff;border-color:var(--accent)}main{min-width:0;padding:22px clamp(16px,3vw,42px) 60px}.tab{display:none}.tab.active{display:block}.section-head{display:flex;justify-content:space-between;gap:16px;align-items:end;margin-bottom:14px}.section-head h2{margin:0;font-size:22px}.note{color:var(--muted);font-size:12px}.decision{border-left:5px solid var(--accent);background:#fff;padding:18px 20px;border-top:1px solid var(--line);border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.decision strong{font-size:20px}.metric-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line);background:#fff;margin:14px 0}.metric{padding:15px;border-right:1px solid var(--line)}.metric:last-child{border:0}.metric b{display:block;font-size:25px}.metric small{color:var(--muted)}.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{background:#fff;border:1px solid var(--line);padding:17px;margin:14px 0;min-width:0}.panel h3{margin:0 0 10px;font-size:16px}.insights{list-style:none;padding:0;margin:0}.insights li{padding:12px 0;border-bottom:1px solid var(--line)}.insights li:last-child{border:0}.badge{display:inline-block;border:1px solid currentColor;padding:2px 6px;border-radius:3px;font-size:11px;font-weight:700}.risk{color:var(--risk)}.good{color:var(--good)}.low{color:var(--warm)}.rank{display:grid;grid-template-columns:minmax(130px,1fr) 2fr auto;gap:9px;align-items:center;padding:8px 0;border-bottom:1px solid var(--line)}.track{height:7px;background:#e9edf2}.fill{height:100%;background:#436d9c}.negative .fill{background:#9c574c}.issue-row{display:grid;grid-template-columns:72px minmax(130px,1.1fr) repeat(4,minmax(70px,.7fr));gap:9px;padding:11px 4px;border-bottom:1px solid var(--line);align-items:center;cursor:pointer}.issue-row:hover{background:#f8fafc}.matrix{position:relative;height:360px;border-left:1px solid #94a3b8;border-bottom:1px solid #94a3b8;background:linear-gradient(90deg,transparent 49.8%,#dbe2ea 50%,transparent 50.2%),linear-gradient(0deg,transparent 49.8%,#dbe2ea 50%,transparent 50.2%)}.bubble{position:absolute;transform:translate(-50%,50%);border:2px solid #fff;outline:1px solid #334155;border-radius:50%;display:flex;align-items:center;justify-content:center;text-align:center;padding:6px;background:#dae7f5;cursor:pointer;font-size:11px}.bubble.p1{background:#f3d8d3;outline-color:#8f3025}.detail{border-left:4px solid #94a3b8;padding-left:14px}.trend-grid{display:grid;grid-template-columns:repeat(8,minmax(70px,1fr));gap:6px;align-items:end;height:230px}.trend-col{display:flex;flex-direction:column;justify-content:end;height:100%;text-align:center}.trend-bar{background:#547aa5;min-height:2px}.trend-col small{font-size:10px;color:var(--muted)}.cards-table{width:100%;border-collapse:collapse;table-layout:fixed}.cards-table th,.cards-table td{border-bottom:1px solid var(--line);padding:9px;text-align:left;vertical-align:top;word-break:break-word}.cards-table th{position:sticky;top:0;background:#f8fafc}.voice-layout{display:grid;grid-template-columns:minmax(250px,.8fr) minmax(0,1.2fr);gap:16px}.voice-list{max-height:620px;overflow:auto;border:1px solid var(--line);background:#fff}.voice-item{padding:12px;border-bottom:1px solid var(--line);cursor:pointer}.voice-item.active{background:#eef4fd;border-left:3px solid var(--accent)}.voice-detail{background:#fff;border:1px solid var(--line);padding:20px;min-width:0}.voice-text{white-space:pre-wrap;word-break:break-word;font-size:15px;line-height:1.8}.empty{padding:28px;text-align:center;color:var(--muted);border:1px dashed #b8c4d1}.modal{position:fixed;inset:0;background:#0008;display:none;align-items:center;justify-content:center;padding:20px;z-index:10}.modal.open{display:flex}.modal-box{background:#fff;max-width:620px;width:100%;padding:22px}.loading{position:fixed;inset:0;background:#fff;display:flex;align-items:center;justify-content:center;z-index:20}.summary-chip{background:#eef2f6;padding:5px 8px;font-size:12px}.confidence{font-size:11px;color:var(--muted)}@media(max-width:900px){.shell{grid-template-columns:1fr}aside{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}.nav{display:flex;overflow:auto;gap:3px}.nav button{width:auto;white-space:nowrap;border-left:0;border-bottom:3px solid transparent}.nav button.active{border-bottom-color:var(--accent)}.filters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.filters label{margin:0}.filter-actions{grid-column:1/-1}.metric-strip{grid-template-columns:repeat(2,1fr)}.metric:nth-child(2){border-right:0}.two,.voice-layout{grid-template-columns:1fr}.issue-row{grid-template-columns:60px 1fr 70px}.issue-row>*:nth-child(n+4){display:none}}@media(max-width:520px){.filters{grid-template-columns:1fr}.metric-strip{grid-template-columns:1fr}.metric{border-right:0;border-bottom:1px solid var(--line)}.two{gap:0}.trend-grid{overflow-x:auto;grid-template-columns:repeat(8,70px)}}"""
  js="""(()=>{const D=window.DASHBOARD_DATA;const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let state={tab:'overview',sentiment:'',rating:'',issue:'',priority:'',manual:'',search:''},selectedVoice=null;function e(s){return String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]))}function filtered(){return D.voices.filter(v=>(!state.sentiment||v.sentiment===state.sentiment)&&(!state.rating||String(v.rating)===state.rating)&&(!state.issue||v.issues.includes(state.issue))&&(!state.priority||D.issues.some(i=>i.priority===state.priority&&i.evidence_ids.includes(v.review_id)))&&(!state.manual||String(v.manual_review)===state.manual)&&(!state.search||(v.text+' '+v.title).toLowerCase().includes(state.search.toLowerCase())))}function opts(id,vals){const x=$(id);[...new Set(vals.filter(Boolean))].sort().forEach(v=>x.insertAdjacentHTML('beforeend',`<option value="${e(v)}">${e(v)}</option>`))}function kpi(r){const av=r.length?(r.reduce((a,x)=>a+x.rating,0)/r.length).toFixed(2):'—',pos=r.filter(x=>['Positive','Strong Positive'].includes(x.sentiment)).length,neg=r.filter(x=>['Negative','Strong Negative'].includes(x.sentiment)).length,p1=D.issues.filter(x=>['P0','P1'].includes(x.priority)&&x.evidence_ids.some(id=>r.some(v=>v.review_id===id))).length;return `<div class=metric><small>评论数</small><b>${r.length}</b><small>当前筛选结果</small></div><div class=metric><small>平均评分</small><b>${av}</b><small>n=${r.length} · 无可比历史</small></div><div class=metric><small>正面 / 负面</small><b>${r.length?(pos/r.length*100).toFixed(1):0}% / ${r.length?(neg/r.length*100).toFixed(1):0}%</b><small>正面n=${pos} · 负面n=${neg}</small></div><div class=metric><small>P0 / P1问题</small><b>${p1}</b><small>按筛选结果可追溯</small></div>`}function rank(items,negative=false){const m=Math.max(1,...items.map(x=>x.count));return items.slice(0,5).map(x=>`<div class="rank ${negative?'negative':''}" data-jump="${negative?e(x.name):''}"><b>${e(x.name)}</b><div class=track><div class=fill style="width:${x.count/m*100}%"></div></div><span>${x.count}条 · ${x.share}%</span></div>`).join('')}function overview(r){$('#overview-kpis').innerHTML=kpi(r);$('#positive-rank').innerHTML=rank(D.positive_values);$('#negative-rank').innerHTML=rank(D.issues,true);$('#insights').innerHTML=D.executive.map(x=>`<li><b>${e(x.conclusion)}</b><div>${e(x.evidence)}</div><div class=note>影响：${e(x.impact)} · 动作：${e(x.action)} <span class="badge ${x.confidence==='Low'?'low':''}">${e(x.confidence)}置信度</span></div></li>`).join('');const u=D.issues.find(x=>['P0','P1'].includes(x.priority));$('#urgent').innerHTML=u?`<div class=detail><span class="badge risk">${u.priority}</span> <b>${e(u.name)}</b><p>${u.count}条 · 负面率${u.negative_rate}% · 平均${u.average_rating}分 · ${e(u.trend)}</p><button class="btn primary" data-issue="${e(u.name)}">查看问题与原声</button></div>`:'<div class=empty>当前筛选下没有P0/P1问题</div>'}function issues(){const list=D.issues;$('#matrix').innerHTML=list.map(x=>`<button class="bubble ${x.priority.toLowerCase()}" data-issue="${e(x.name)}" style="left:${Math.max(8,x.frequency_score)}%;bottom:${Math.max(8,x.impact_score)}%;width:${42+x.count*3}px;height:${42+x.count*3}px" title="${e(x.name)}：${x.count}条，影响${x.impact_score}">${e(x.name)}</button>`).join('');$('#issue-list').innerHTML=list.map(x=>`<div class=issue-row data-issue="${e(x.name)}"><span class="badge ${x.priority==='P1'?'risk':''}">${x.priority}</span><b>${e(x.name)}</b><span>${x.count}条</span><span>负面${x.negative_rate}%</span><span>${e(x.trend)}</span><span>${e(x.confidence)}</span></div>`).join('');showIssue(list[0]?.name)}function showIssue(name){const x=D.issues.find(i=>i.name===name);if(!x)return;$('#issue-detail').innerHTML=`<h3>${e(x.name)} <span class="badge ${x.priority==='P1'?'risk':''}">${x.priority}</span></h3><p><b>为什么：</b>${x.count}条，占73条的${x.share}%；负面率${x.negative_rate}%；平均${x.average_rating}分；score ${x.priority_score}。</p><p><b>趋势：</b>${e(x.trend)} · <b>置信度：</b>${e(x.confidence)}</p><p><b>可能根因：</b>${e(x.root_cause)}</p><p><b>产品：</b>${e(x.product_action)}</p><p><b>营销：</b>${e(x.marketing_action)}</p><p><b>客服：</b>${e(x.support_action)}</p><button class="btn primary" data-to-voices="${e(x.name)}">查看${x.count}条相关原声</button>`}function trend(){const max=Math.max(...D.trends.map(x=>x.reviews));$('#trend-bars').innerHTML=D.trends.map(x=>`<div class=trend-col title="${x.month}：${x.reviews}条，均分${x.average_rating}，负面率${x.negative_rate}%"><div><b>${x.reviews}</b><small>条</small></div><div class=trend-bar style="height:${x.reviews/max*150}px"></div><small>${x.month.slice(5)}月</small><small>负面${x.negative_rate}%</small></div>`).join('');$('#trend-table').innerHTML=D.trends.map(x=>`<tr><td>${x.month}</td><td>${x.reviews}</td><td>${x.average_rating}</td><td>${x.negative_rate}%</td><td>${x.strong_negative_rate}%</td><td><span class="badge low">${x.confidence}</span></td></tr>`).join('')}function product(){const rows=D.backlog;$('#backlog').innerHTML=rows.length?rows.map(x=>`<tr><td>${e(x['Issue ID'])}</td><td><span class="badge risk">${e(x['优先级'])}</span></td><td>${e(x['问题或需求'])}</td><td>${e(x['评论数量'])}</td><td>${e(x['趋势'])}</td><td>${e(x['建议动作'])}</td><td>${e(x['负责人建议'])}</td><td>${e(x['状态'])}</td></tr>`).join(''):'<tr><td colspan=8>没有达到Backlog阈值的问题</td></tr>'}function marketing(){const good=D.marketing.filter(x=>x['类型']==='应强化的卖点'),concern=D.marketing.filter(x=>x['类型']!=='应强化的卖点');$('#marketing-good').innerHTML=good.map(x=>`<li><b>${e(x['用户认可价值'])}</b> · ${e(x['评论数量'])}条 / ${e(x['评论占比'])}<div>${e(x['推荐营销表达'])}</div><div class=note>${e(x['适用渠道'])} · ${e(x['证据强度'])}置信度</div></li>`).join('');$('#marketing-concern').innerHTML=concern.map(x=>`<li><b>${e(x['用户认可价值'])}</b> · ${e(x['评论数量'])}条<div>${e(x['推荐营销表达'])}</div><div class=note>避免：${e(x['需要避免的表达'])}</div></li>`).join('')}function voices(){const r=filtered();$('#voice-count').textContent=`${r.length}条`;$('#voice-list').innerHTML=r.slice(0,100).map(v=>`<div class="voice-item ${v.review_id===selectedVoice?'active':''}" data-voice="${v.review_id}"><b>${'★'.repeat(v.rating)} ${e(v.title)}</b><div class=note>${v.date} · ${e(v.sentiment)} · ${e(v.issues[0]||v.values[0]||'未分类')}</div><div>${e(v.text.slice(0,95))}${v.text.length>95?'…':''}</div></div>`).join('')||'<div class=empty>当前筛选没有评论</div>';if(!selectedVoice&&r[0])selectedVoice=r[0].review_id;showVoice(r.find(x=>x.review_id===selectedVoice)||r[0])}function showVoice(v){if(!v){$('#voice-detail').innerHTML='<div class=empty>请选择一条评论</div>';return}$('#voice-detail').innerHTML=`<h3>${e(v.title)}</h3><div class=note>${v.date} · ${'★'.repeat(v.rating)} · ${e(v.sentiment)} · ${e(v.confidence)}置信度</div><p><b>问题主题：</b>${e(v.issues.join(' / ')||'无')}<br><b>用户价值：</b>${e(v.values.join(' / ')||'无')}<br><b>使用场景：</b>${e(v.scenarios.join(' / ')||'评论未明确')}<br><b>问题归属：</b>${e(v.owner)}<br><b>人工复核：</b>${v.manual_review?'需要':'不需要'}</p><div class=voice-text lang=ja>${e(v.text)}</div><p><button class=btn id=copyVoice>复制原文</button> <a class="btn primary" href="${e(v.url)}" target=_blank rel=noopener>打开Amazon原始链接</a></p>`;$('#copyVoice').onclick=()=>navigator.clipboard?.writeText(v.text)}function quality(){$('#quality').innerHTML=`<li>2星Positive：修正前 <b>${D.quality.two_star_positive_before}</b> 条，修正后 <b>${D.quality.two_star_positive_after}</b> 条。</li><li>${e(D.quality.topic_audit)}</li><li>空正文：${D.quality.empty}条；评论ID重复：0条。</li><li>长期趋势：<span class="badge low">数据不足</span>。8个月样本不均，且缺失17条。</li>`}function render(){const r=filtered();$('#filter-summary').textContent=`当前筛选 ${r.length} 条`;$(`#${state.tab}`).classList.add('active');if(state.tab==='overview')overview(r);if(state.tab==='issues')issues();if(state.tab==='trend')trend();if(state.tab==='product')product();if(state.tab==='marketing')marketing();if(state.tab==='voices')voices();if(state.tab==='quality')quality();bind()}function bind(){$$('[data-issue]').forEach(x=>x.onclick=()=>showIssue(x.dataset.issue));$$('[data-to-voices]').forEach(x=>x.onclick=()=>{state.issue=x.dataset.toVoices;$('#issueFilter').value=state.issue;go('voices')});$$('[data-jump]').forEach(x=>{if(x.dataset.jump)x.onclick=()=>{state.issue=x.dataset.jump;$('#issueFilter').value=state.issue;go('issues')}});$$('[data-voice]').forEach(x=>x.onclick=()=>{selectedVoice=x.dataset.voice;voices()})}function go(tab){state.tab=tab;$$('.tab').forEach(x=>x.classList.remove('active'));$$('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));render();scrollTo({top:0,behavior:'instant'})}$$('.nav button').forEach(x=>x.onclick=()=>go(x.dataset.tab));opts('#sentimentFilter',D.voices.map(x=>x.sentiment));opts('#issueFilter',D.issues.map(x=>x.name));['sentiment','rating','issue','priority','manual'].forEach(k=>$(`#${k}Filter`).onchange=e=>{state[k]=e.target.value;render()});$('#search').oninput=e=>{state.search=e.target.value;render()};$('#reset').onclick=()=>{state={tab:state.tab,sentiment:'',rating:'',issue:'',priority:'',manual:'',search:''};$$('.filters select,.filters input').forEach(x=>x.value='');render()};$('#export').onclick=()=>{const r=filtered(),cols=['review_id','date','rating','sentiment','title','text','url'],csv=[cols.join(','),...r.map(v=>cols.map(k=>'"'+String(v[k]??'').replaceAll('"','""')+'"').join(','))].join('\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='filtered_reviews.csv';a.click();URL.revokeObjectURL(a.href)};$('#statusBtn').onclick=()=>$('#statusModal').classList.add('open');$('#closeModal').onclick=()=>$('#statusModal').classList.remove('open');$('#loading').remove();go('overview')})()"""
  index=f"""<!doctype html><html lang='zh-CN'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Customer Review Intelligence V2</title><link rel='stylesheet' href='dashboard.css'></head><body><div class='loading' id='loading'>正在载入可审计VOC数据…</div><header><h1>Customer Review Intelligence</h1><div class='meta'><span>SwitchBot AI Art Canvas</span><span>Amazon Japan</span><span>{esc(data['meta']['date_range'])}</span><button class='status' id='statusBtn'>● 部分完整 · 73 / 90</button></div></header><div class='shell'><aside><nav class='nav'><button class='active' data-tab='overview'>总览</button><button data-tab='issues'>负面问题</button><button data-tab='trend'>趋势分析</button><button data-tab='product'>产品改善</button><button data-tab='marketing'>营销洞察</button><button data-tab='voices'>用户原声</button><button data-tab='quality'>数据质量</button></nav><div class='filters'><h3>全局筛选</h3><label>情绪</label><select id='sentimentFilter'><option value=''>全部</option></select><label>评分</label><select id='ratingFilter'><option value=''>全部</option><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select><label>问题主题</label><select id='issueFilter'><option value=''>全部</option></select><label>优先级</label><select id='priorityFilter'><option value=''>全部</option><option>P1</option><option>P2</option><option>Monitor</option></select><label>人工复核</label><select id='manualFilter'><option value=''>全部</option><option value='true'>需要</option><option value='false'>不需要</option></select><label>关键词</label><input id='search' placeholder='搜索日文评论'><div class='filter-actions'><button class='btn' id='reset'>重置</button><button class='btn' id='export'>导出筛选CSV</button></div><p id='filter-summary' class='summary-chip'></p></div></aside><main><section class='tab' id='overview'><div class='section-head'><div><h2>总览</h2><div class='note'>30秒判断：满意度、价值、风险和下一步</div></div></div><div class='decision'><strong>整体满意度较高，但显示体验的预期差是首要风险。</strong><div>73条可审计Amazon评论平均4.37分；高评分不能掩盖近距离颗粒感、暗部与色彩还原问题。结论置信度中等，缺失17条可能改变比例。</div></div><div class='metric-strip' id='overview-kpis'></div><div class='panel'><h3>管理层结论</h3><ul class='insights' id='insights'></ul></div><div class='two'><div class='panel'><h3>用户最认可什么</h3><div id='positive-rank'></div></div><div class='panel'><h3>用户最不满意什么</h3><div id='negative-rank'></div></div></div><div class='panel'><h3>现在先改什么</h3><div id='urgent'></div></div></section><section class='tab' id='issues'><div class='section-head'><div><h2>负面问题</h2><div class='note'>回答：问题在哪里、为什么紧急、如何进入用户原声</div></div></div><div class='two'><div class='panel'><h3>频率 × 影响度矩阵</h3><div class='matrix' id='matrix'></div><div class='note'>横轴频率，纵轴影响；样本少的问题默认Monitor。</div></div><div class='panel detail' id='issue-detail'></div></div><div class='panel'><h3>问题清单</h3><div class='issue-row note'><span>优先级</span><span>问题</span><span>数量</span><span>负面率</span><span>趋势</span><span>置信度</span></div><div id='issue-list'></div></div></section><section class='tab' id='trend'><div class='section-head'><div><h2>趋势分析</h2><div class='note'>回答：哪些问题正在恶化；当前只能判断短期波动</div></div></div><div class='panel'><h3>月度评论量与负面率</h3><div class='trend-grid' id='trend-bars'></div></div><div class='panel'><table class='cards-table'><thead><tr><th>月份</th><th>评论数</th><th>平均评分</th><th>负面率</th><th>强负面率</th><th>置信度</th></tr></thead><tbody id='trend-table'></tbody></table><p class='note'>没有可比上期完整样本，禁止将单月变化解释为长期趋势。</p></div></section><section class='tab' id='product'><div class='section-head'><div><h2>产品改善Backlog</h2><div class='note'>回答：产品先改什么、谁负责、如何验收</div></div><a class='btn' href='product_improvement_backlog.csv' download>导出CSV</a></div><div class='panel'><table class='cards-table'><thead><tr><th>ID</th><th>优先级</th><th>问题</th><th>评论数</th><th>趋势</th><th>建议动作</th><th>负责人</th><th>状态</th></tr></thead><tbody id='backlog'></tbody></table></div></section><section class='tab' id='marketing'><div class='section-head'><div><h2>营销洞察</h2><div class='note'>回答：应该强化什么、哪些顾虑必须提前处理</div></div><a class='btn' href='marketing_insight_playbook.csv' download>导出CSV</a></div><div class='two'><div class='panel'><h3>应强化的真实价值</h3><ul class='insights' id='marketing-good'></ul></div><div class='panel'><h3>需要消除的购买顾虑</h3><ul class='insights' id='marketing-concern'></ul></div></div><div class='panel'><h3>渠道应用</h3><p><b>LP / Amazon / Rakuten：</b>增加观看距离、环境光、近景/远景对比与本地容量FAQ。</p><p><b>广告：</b>优先展示家庭回忆、儿童作品和室内融合场景；避免“高精细液晶式”表达。</p><p><b>EDM / LINE：</b>按家庭照片、艺术内容、季节换画细分主题。</p><p><b>PR / KOL：</b>必须实测亮度、色彩、颗粒感、图片切换和S/M/L观看距离。</p></div></section><section class='tab' id='voices'><div class='section-head'><div><h2>用户原声 <span id='voice-count' class='summary-chip'></span></h2><div class='note'>左侧选评论，右侧阅读全文并追溯Amazon</div></div></div><div class='voice-layout'><div class='voice-list' id='voice-list'></div><div class='voice-detail' id='voice-detail'></div></div></section><section class='tab' id='quality'><div class='section-head'><div><h2>数据质量</h2><div class='note'>回答：这些结论能信到什么程度</div></div></div><div class='panel'><ul class='insights' id='quality'></ul></div><div class='panel'><h3>数据缺失影响</h3><p>Amazon页面显示90条正文评论，当前仅73条可审计。缺失17条可能改变平均评分、负面率、主题排序和P1判断，因此所有比例都标注n，长期趋势保持低置信度。</p><a class='btn' href='data_validation_report.md'>查看验证报告</a></div></section></main></div><div class='modal' id='statusModal'><div class='modal-box'><h2>数据完整性：部分完整</h2><p>原始页面显示：90条<br>成功分析：73条<br>缺失：17条<br>去重：0条<br>无正文：0条<br>无法分类：0条</p><p><b>影响：</b>{esc(data['meta']['impact'])}</p><button class='btn primary' id='closeModal'>关闭</button></div></div><script>window.DASHBOARD_DATA={json.dumps(data,ensure_ascii=False)}</script><script src='dashboard.js'></script></body></html>"""
  js=js.replace("join('\n'),blob", "join('\\\\n'),blob")
  js=js.replace("let state={tab:'overview'", "let state={evidenceIds:null,tab:'overview'")
  js=js.replace("&&(!state.priority||", "&&(!state.evidenceIds||state.evidenceIds.includes(v.review_id))&&(!state.priority||")
  js=js.replace("state.issue=x.dataset.toVoices;$('#issueFilter').value=state.issue", "state.issue=x.dataset.toVoices;state.evidenceIds=D.issues.find(i=>i.name===state.issue)?.evidence_ids||null;$('#issueFilter').value=state.issue")
  js=js.replace("state[k]=e.target.value;render()", "state[k]=e.target.value;if(k==='issue')state.evidenceIds=null;render()")
  js=js.replace("state={tab:state.tab", "state={evidenceIds:null,tab:state.tab")
  js=js.replace("$('#loading').remove();go('overview')", "$('#toggleFilters').onclick=()=>$('.filters').classList.toggle('open');$('#loading').remove();go('overview')")
  index=index.replace("<h3>全局筛选</h3>", "<h3>全局筛选 <button class='btn filter-toggle' id='toggleFilters'>展开 / 收起</button></h3>")
  css += "@media(min-width:901px){.filter-toggle{display:none}}@media(max-width:900px){.filters:not(.open)>label,.filters:not(.open)>select,.filters:not(.open)>input,.filters:not(.open)>.filter-actions{display:none}.filter-toggle{float:right;padding:3px 7px}.filters h3{grid-column:1/-1;margin:0}.filters #filter-summary{grid-column:1/-1}}"
